	["hint.scr_zt_char_mob"] = "Preferred Mob of the Dead character, solo or co-op. Host wins ties; tied non-hosts draw randomly. RANDOM keeps the stock choice unless displaced. No T7 stock map uses this cast.",
	["hint.scr_zt_char_origins"] = "Preferred Origins character in either game, solo or co-op; saved separately from Primis. Host wins ties; tied non-hosts draw randomly. RANDOM keeps stock unless displaced. Required co-op story roles are preserved.",
	["hint.scr_zt_char_primis"] = "Preferred character on The Giant, Der Eisendrache, Zetsubou, Gorod Krovi or Revelations, solo or co-op. Origins is separate. Host wins ties; tied non-hosts draw randomly. Required co-op story roles are preserved.",
	["hint.scr_zt_char_soe"] = "Preferred Shadows of Evil character, solo or co-op. Host wins ties; tied non-hosts draw randomly. RANDOM keeps the stock choice unless displaced. No T6 stock map uses this cast.",
	["hint.scr_zt_char_ultimis"] = "Preferred character on BO3 Moon, Ascension, Shangri-La, Kino, Nacht, Verruckt or Shi No Numa. Solo and co-op: host wins ties; tied non-hosts draw randomly. Required co-op roles are preserved. No T6 stock map uses Ultimis.",
	["hint.scr_zt_char_victis"] = "Preferred character on TranZit, Die Rise, or Buried. Solo and co-op: host wins ties; tied non-hosts draw randomly. RANDOM keeps the stock choice unless displaced. No T7 stock map uses Victis.",
	["hint.zt_auto_restart"] = "Restart the current level after the normal game-over results have been shown. DEFAULT is OFF.",
	["hint.zt_bleedout_time"] = "Percentage of the map's normal last-stand bleed-out duration. GAME DEFAULT preserves the map's timer.",
	["hint.zt_box_lock"] = "Prevent the standard Mystery Box from randomly relocating after normal purchases. Explicit scripted or quest-owned box moves remain map-controlled. OFF preserves every map-authored relocation rule.",
	["hint.zt_box_no_repeat"] = "Avoid offering the same weapon on two consecutive standard Mystery Box pulls by the same player when another eligible registered weapon exists. OFF keeps stock selection. Map-authored special picks and weapon eligibility remain unchanged.",
	["hint.zt_box_price_multiplier"] = "Percentage of each standard Mystery Box location's map-authored normal price. GAME DEFAULT preserves each location's own price. FREE affects ordinary box purchases but does not change the Fire Sale price.",
	["hint.zt_box_quality"] = "Adjust the standard Mystery Box weapon pool. NO WONDER WEAPONS removes registered wonder weapons; IMPROVED raises the chance of stronger registered weapons; FULL MAP POOL bypasses map-authored weighting while preserving stock ownership and quest-safety checks.",
	["hint.zt_challenge_gun_game"] = "Progress each player through a compatible registered weapon sequence using zombie kills. The challenge disables itself if the map cannot supply a safe progression list.",
	["hint.zt_challenge_no_box"] = "Disable the standard Mystery Box. Custom scripted weapon lotteries remain untouched unless they register the stock box capability.",
	["hint.zt_challenge_no_pap"] = "Disable the standard Pack-a-Punch interaction when the map exposes it safely. Scripted upgrade quests remain map-controlled and are reported if they cannot be disabled.",
	["hint.zt_challenge_no_perks"] = "Disable standard perk acquisition and ZTweaks starting-perk grants. Map quest rewards that cannot be safely intercepted are reported as a compatibility limitation.",
	["hint.zt_challenge_one_box"] = "Allow each player one completed standard Mystery Box purchase. Maps without the stock box-use notification disable this rule safely.",
	["hint.zt_challenge_one_weapon_slot"] = "Limit normal weapon pickups to one primary slot through the stock weapon-limit callback. ZTweaks will not grant a secondary starting weapon. Map-owned weapon limits and scripted quest inventory remain in control.",
	["hint.zt_challenge_random_loadout"] = "Choose an independent compatible registered starting weapon loadout for each player. Explicit primary and secondary starting-weapon choices take precedence.",
	["hint.zt_challenge_random_rules"] = "Select one shared, compatible challenge rule for the match and report the chosen rule to the host. Explicitly enabled challenge rows are never overwritten.",
	["hint.zt_challenge_rising_damage"] = "Increase ordinary player weapon and melee damage against standard zombies each round after round 1. The selected percentage is added per round, up to 500% of normal damage. OFF preserves the map's damage. Quest actors, friendly NPCs, and map-owned damage callbacks remain protected.",
	["hint.zt_challenge_starting_room"] = "Keep players in the map's starting zone only when the map safely identifies its exit doors. The challenge disables itself rather than guessing at scripted progression blockers.",
	["hint.zt_challenge_wall_only"] = "Disable standard non-wall weapon acquisition while leaving wall buys enabled. Unsupported map-authored reward systems are reported instead of forcibly removed.",
	["hint.zt_death_points_retained"] = "Percentage of points kept at the next standard spectator respawn, after any stock minimum-respawn score is applied. The rest is lost. GAME DEFAULT preserves the map's death penalty; custom death-score rules remain map-owned.",
	["hint.zt_disable_carpenter_drops"] = "Exclude this type from regular random drops when another eligible type exists. Scripted drops are unchanged. If all are excluded, one eligible type remains to avoid stalling the game.",
	["hint.zt_disable_double_points_drops"] = "Exclude this type from regular random drops when another eligible type exists. Scripted drops are unchanged. If all are excluded, one eligible type remains to avoid stalling the game.",
	["hint.zt_disable_fire_sale_drops"] = "Exclude this type from regular random drops when another eligible type exists. Scripted drops are unchanged. If all are excluded, one eligible type remains to avoid stalling the game.",
	["hint.zt_disable_insta_kill_drops"] = "Exclude this type from regular random drops when another eligible type exists. Scripted drops are unchanged. If all are excluded, one eligible type remains to avoid stalling the game.",
	["hint.zt_disable_max_ammo_drops"] = "Exclude this type from regular random drops when another eligible type exists. Scripted drops are unchanged. If all are excluded, one eligible type remains to avoid stalling the game.",
	["hint.zt_disable_nuke_drops"] = "Exclude this type from regular random drops when another eligible type exists. Scripted drops are unchanged. If all are excluded, one eligible type remains to avoid stalling the game.",
	["hint.zt_disable_stock_aat"] = "Prevent stock Alternate Ammo Types on compatible upgraded weapons, including Pack-a-Punch rerolls. Existing map exemptions remain in force. Custom AAT systems outside the stock registry stay map-owned. OFF preserves stock behavior.",
	["hint.zt_down_limit"] = "Maximum ordinary co-op downs before stock bleeds the player out instead of allowing another revive. UNLIMITED keeps stock co-op's unlimited downs. Solo auto-revive, special-role and non-composable map routes stay stock and report unavailable.",
	["hint.zt_experimental_tweaks"] = "Allow selected stock-map-only tweaks. Custom-map support may be limited. OFF makes every experimental tweak inert even if its own saved option is ON; it does not relax compatibility checks or other Z mods' ownership.",
	["hint.zt_fall_damage"] = "Scale standard fall damage or turn it off. GAME DEFAULT delegates to the map; custom scripted hazards are not reclassified as falls.",
	["hint.zt_fast_barrier_rebuild"] = "Reduce the pause between standard barrier-board repairs. Requires Experimental Tweaks. Available only on recognized stock maps with the stock blocker system; custom-map support may be limited. A map-authored repair delay always wins.",
	["hint.zt_fire_sale_box_price"] = "Point cost of standard Mystery Boxes while Fire Sale is active. GAME DEFAULT preserves the stock or map-authored sale price. Normal box prices and map-authored nonstandard weapon lotteries remain untouched.",
	["hint.zt_game_start_delay"] = "Additional seconds before ordinary zombies begin spawning in the first round. GAME DEFAULT preserves the map's own delay; this does not remove the stock round-opening presentation or map-authored scripted waits.",
	["hint.zt_gobblegum_rounds"] = "Percentage of each round-limited GobbleGum's stock round count. Values round to at least one round. Event-limited gums are not changed.",
	["hint.zt_gobblegum_time"] = "Percentage of each time-limited GobbleGum's stock duration in seconds. Values round to at least one second. GAME DEFAULT preserves every gum's registered duration.",
	["hint.zt_gobblegum_uses"] = "Percentage of each activation-limited GobbleGum's stock number of uses. Values round to at least one use. GAME DEFAULT preserves every gum's registered limit.",
	["hint.zt_headshots_only"] = "Require headshots for standard zombie kills using the stock Zombies rule. OFF is inert and leaves the map's own game setting unchanged.",
	["hint.zt_health_regen_delay"] = "Percentage of the stock delay before health regeneration begins after damage. GAME DEFAULT preserves the map's delay. This does not change the regeneration rate or map-owned healing systems.",
	["hint.zt_keep_weapons_bleedout"] = "Restore a player's standard weapon inventory after bleeding out and respawning. OFF leaves the map's death and respawn loadout untouched.",
	["hint.zt_lose_perks_on_down"] = "Choose how many perks are removed through the standard down path. MAP DEFAULT keeps the map rule; NONE attempts to preserve every standard registered perk.",
	["hint.zt_max_ammo_reload"] = "After a standard Max Ammo pickup refills reserves, also refill the magazines of eligible held firearms. OFF preserves stock behavior. Quest equipment, excluded weapons, custom ammo systems, and a replacement weapon acquired during pickup remain untouched.",
	["hint.zt_max_equipment"] = "Carried tactical or placeable-equipment capacity. GAME DEFAULT leaves each item and map in control; enabled values initialize newly granted equipment to this amount and cap later grants at it.",
	["hint.zt_max_grenades"] = "Carried lethal-grenade capacity. GAME DEFAULT leaves the weapon and map limit untouched; enabled values initialize newly granted grenades to this amount and cap later grants at it.",
	["hint.zt_melee_damage"] = "Percentage of normal player melee damage dealt to zombies. GAME DEFAULT leaves knife, melee weapon, perk, and map behavior untouched.",
	["hint.zt_next_map"] = "Choose the map selected after every completed game. This works independently of Auto Restart: with Auto Restart off, ZTweaks changes the lobby selection without launching it. Random choices exclude the current map when another valid map exists.",
	["hint.zt_no_explosive_self_damage"] = "Prevent a player's own grenades, launchers, and other standard explosives from damaging that player. OFF leaves the stock damage callback untouched.",
	["hint.zt_pap_damage_multiplier"] = "Scale ordinary hits from registered Pack-a-Punched weapons against standard zombies. GAME DEFAULT preserves normal damage. Custom upgrades and map-owned damage callbacks remain unchanged.",
	["hint.zt_perk_limit"] = "Maximum perks a player may hold. DEFAULT leaves the map or ZShare in control; a number replaces the base limit while preserving map-added slots; UNLIMITED removes the limit. ZTweaks takes precedence over ZShare when enabled.",
	["hint.zt_perk_price_multiplier"] = "Scale the price of standard powered perk machines. GAME DEFAULT leaves prices unchanged. Custom perk prices and later map changes remain map-owned. BO2 has no safe equivalent.",
	["hint.zt_player_health"] = "Percentage of normal player health. GAME DEFAULT leaves the map in control. Perks continue to scale from the modified base health.",
	["hint.zt_player_speed"] = "Percentage of normal player movement speed applied at spawn. GAME DEFAULT leaves movement untouched so map-authored movement rules remain authoritative.",
	["hint.zt_point_gain"] = "Percentage of normal positive score awards, including zombie damage, kills, headshots, and standard repairs. GAME DEFAULT leaves every map-authored award unchanged; point costs are never scaled.",
	["hint.zt_powerup_drop_rate"] = "Multiplier for stock regular score-threshold power-up drops. Higher values reach each drop threshold sooner. GAME DEFAULT preserves the map threshold; max-per-round, random kill drops, and scripted drops remain untouched.",
	["hint.zt_powerup_effect_time"] = "Percentage of each timed power-up's map-selected effect duration. This includes team, global, and player-only timed effects registered through the stock power-up system. GAME DEFAULT preserves every map-authored duration.",
	["hint.zt_powerup_ground_time"] = "Seconds a normal dropped power-up remains collectible before its stock flashing phase begins. GAME DEFAULT uses 15 seconds. Map-authored custom lifetimes, infinite quest drops, and BO3 Temporal Gift remain authoritative.",
	["hint.zt_powerup_max_per_round"] = "Maximum regular score-threshold power-up drops allowed in each round. GAME DEFAULT preserves the map's own cap. Scripted rewards, boss drops, quest drops, and other map-authored power-ups remain untouched.",
	["hint.zt_powerup_stacking"] = "Choose how a repeated standard timed power-up affects its active timer. REFRESH restarts the configured duration, EXTEND adds another duration, and IGNORE preserves the current timer.",
	["hint.zt_random_starting_perks"] = "Number of random perks granted independently to each player when they spawn. NONE is inert. Perks are chosen without duplicates from those registered by the current map; if fewer are available, every available perk is granted.",
	["hint.zt_reserve_ammo"] = "Scale the native reserve ammo granted to selected or inherited starting weapons while retaining each weapon's own magazine and ammo type. Values above an asset's hard capacity safely clamp and report degraded compatibility. GAME DEFAULT preserves stock ammo.",
	["hint.zt_revive_time"] = "Percentage of the map's normal revive interaction time. GAME DEFAULT preserves map, perk, and equipment modifiers.",
	["hint.zt_round_bonus"] = "Extra points awarded to each active player when a standard round ends. GAME DEFAULT adds no bonus. Map-authored round rewards remain unchanged.",
	["hint.zt_round_delay"] = "Seconds between a completed round and the next round. GAME DEFAULT preserves the map's delay. INSTANT removes only the standard between-round wait; round-change HUD and map-authored scripted waits remain intact.",
	["hint.zt_secondary_starting_weapon"] = "Optional additional starting weapon class. MAP DEFAULT grants no extra weapon. This is separate from the primary Starting Weapon override and does not replace or select the primary.",
	["hint.zt_spawn_protection"] = "Seconds of damage immunity after a player spawns or respawns. GAME DEFAULT adds no ZTweaks protection and leaves map-authored protection alone.",
	["hint.zt_start_all_perks"] = "Grant every perk registered by the current map at spawn. OFF is inert. When enabled, this takes precedence over Random Starting Perks.",
	["hint.zt_start_doors_open"] = "Open ordinary, delayed, and power-gated purchasable doors, barriers, debris, and airlocks for free through their stock blocker paths after the first player spawns. Kill-counter and custom scripted quest blockers remain map-controlled.",
	["hint.zt_start_power_on"] = "Turn on the map's stock power consumers at match start. Global systems use the common power state; zoned systems activate published perk, random-perk, and door power zones. Activation rituals/generators and their counters remain map-controlled; downstream systems that listen to real power, including stock traversal and Pack-a-Punch, still unlock.",
	["hint.zt_starting_ammo"] = "Percentage of normal starting ammo for the player's starting weapons. GAME DEFAULT preserves stock ammo; EMPTY leaves the weapon with no reserve or loaded rounds.",
	["hint.zt_starting_equipment"] = "Tactical or placeable equipment given at spawn. MAP DEFAULT preserves the map choice. Unsupported items fail closed instead of substituting a different type.",
	["hint.zt_starting_equipment_count"] = "Amount of the active tactical or placeable equipment given at spawn. GAME DEFAULT preserves stock start ammo. When Max Equipment is enabled, the lower value wins at spawn.",
	["hint.zt_starting_grenade"] = "Lethal grenade type given at spawn. MAP DEFAULT preserves the map's choice. A selected type is used only when that map has registered a compatible grenade.",
	["hint.zt_starting_grenade_count"] = "Number of lethal grenades given at spawn. GAME DEFAULT preserves stock start ammo. When Max Grenades is also enabled, the lower value wins at spawn.",
	["hint.zt_starting_points"] = "Points given to each player when a new match begins. GAME DEFAULT preserves the map's normal behavior, including BO3's stock starting-round calculation of 500 points per selected round.",
	["hint.zt_starting_round"] = "Round used when a new match begins. GAME DEFAULT leaves the map's normal starting round and starting-points calculation untouched.",
	["hint.zt_starting_weapon"] = "Weapon class that replaces the map's primary starting weapon. MAP DEFAULT preserves the map choice. If the selected class is unavailable, ZTweaks safely keeps the map default.",
	["hint.zt_starting_weapon_aat"] = "Give the Pack-a-Punched starting weapon slots selected above a stock Alternate Ammo Type. RANDOM chooses one registered stock AAT per spawn. MAP DEFAULT adds no AAT. Unsupported weapons and maps remain unchanged.",
	["hint.zt_starting_weapon_upgraded"] = "Spawn with the selected ZTweaks starting weapon slots Pack-a-Punched when the map registers a safe upgraded variant. MAP DEFAULT leaves both slots unmodified.",
	["hint.zt_teddy_chance"] = "Chance of a teddy bear on each eligible standard Mystery Box pull. GAME DEFAULT keeps the map's chance. The map's minimum pulls, no-fly-away boxes, Fire Sales, and custom chance callbacks remain protected; 0% prevents ordinary teddy-bear moves.",
	["hint.zt_trap_price_multiplier"] = "Percentage of each standard purchasable trap's map-authored price. GAME DEFAULT leaves the trap alone. Custom trap purchase callbacks and later map price changes remain map-controlled; maps without standard purchase traps are unaffected.",
	["hint.zt_weapon_damage"] = "Percentage of normal player weapon damage dealt to zombies. Melee uses its own setting. GAME DEFAULT preserves the stock and custom-map damage path.",
	["hint.zt_wunderfizz_price_multiplier"] = "Scale the standard Wunderfizz price, including its purchase hint and stock refund. GAME DEFAULT leaves the map's price unchanged. If a map later takes over the price, its value wins. BO2 has no verified equivalent.",
	["hint.zt_zombie_damage"] = "Percentage of direct damage dealt to players by ordinary zombies. GAME DEFAULT preserves map damage; bosses, quest actors, traps, and environmental damage remain map-controlled.",
	["hint.zt_zombie_health"] = "Percentage of the map's normal zombie-health curve. GAME DEFAULT leaves both starting health and round-to-round growth untouched. RANDOM independently chooses one listed percentage when each match initializes.",
	["hint.zt_zombie_spawn_rate"] = "Percentage of the map's normal standard-zombie spawn cadence. Higher values shorten the delay between ordinary spawns. GAME DEFAULT is inert; special, objective, and scripted spawners remain map-controlled.",
	["hint.zt_zombie_speed"] = "Percentage of the map's normal zombie speed curve. GAME DEFAULT is inert. RANDOM independently chooses one listed percentage when each match initializes. Standard round zombies are scaled; map-owned special enemies remain untouched.",
	["hint.zt_zombies_per_round"] = "Percentage of the standard zombie count calculated for each round. GAME DEFAULT is inert. Scripted special rounds and objective spawns remain map-controlled.",
